F=np.load('feats.npz'); y=F['y']; folds=np.load('folds.npy')
def std(X,tr): 
    mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def kr_cv(Xfun, lam, kernel='lin', gamma=None):
    accs=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        X=Xfun(tr)
        if kernel=='lin': K=X@X[tr].T
        else:
            sq=(X**2).sum(1); D=sq[:,None]+sq[tr][None,:]-2*X@X[tr].T; K=np.exp(-gamma*D/X.shape[1])
        Y=np.eye(8)[y[tr]]-1/8
        a=np.linalg.solve(K[tr]+lam*np.eye(tr.sum()),Y)
        accs.append((np.argmax(K[te]@a,1)==y[te]).mean())
    return round(np.mean(accs),4)
for Ls in [[12],[6],[6,12],[0,6,12],[3,6,9,12],list(range(13)),list(range(4,13))]:
    fn=lambda tr: np.concatenate([std(F[f'M{L}'],tr) for L in Ls],1)/np.sqrt(len(Ls))
    print(Ls, [kr_cv(fn,l) for l in [30,100,300,1000]])
for L in [6,12]:
    fn=lambda tr: std(F[f'M{L}'],tr)
    for g in [0.1,0.3,1]:
        print('rbf',L,g,[kr_cv(fn,l,'rbf',g) for l in [0.01,0.1,1]])
